from lib import *
S = SS('f93')
R = J('f93'); cs = R['cost']; st = R['stale']; tg = R['trigger']
steps = [
    step("默认 expire_on_commit=True:commit 之后读 n.title 与 n.id,新发 1 条 SELECT note.id, note.title, note.ver, note.updated FROM note WHERE ...(把整行重新取回);设成 False 后新发 0 条。所以「创建一个对象、commit、返回它的 id」这个最常见的写法,默认会多一次往返。", t=tl(S(1)), mark=lidx(S(1), 'expire_on_commit=True'), done=lidx(S(1), 'expire_on_commit=False'), kv=KV([['True', 'commit 后读属性多 1 条 SELECT'], ['False', '0 条']], ['True'])),
    step("请求结束、session 被清理之后读属性:expire_on_commit=True 时抛 DetachedInstanceError(commit 后属性已过期,又没有 session 可以重新加载);False 时读到 'x'(属性还留在对象里)。把对象带出请求之外用(放缓存、传给后台线程)的人容易撞上这个。", t=tl(S(2)), mark=lidx(S(2), 'DetachedInstanceError'), done=lidx(S(2), '读到'), kv=KV([['True', '请求外读属性 DetachedInstanceError'], ['False', '能读到,但可能是旧值']], ['True'])),
    step(f"陈旧数据:对象创建后,另一个连接改了同一行;本会话改 title 并 commit,库里的 ver 是 2(触发器每次 UPDATE 加 1)。expire_on_commit=True 时 n.ver = {st['True'][2]}(commit 后重新读取);False 时 n.ver = {st['False'][2]}(还是创建时的旧值)——对象不知道库里的 ver 已经变了。", t=tl(S(3)), mark=lidx(S(3), 'expire_on_commit=False'), done=lidx(S(3), 'expire_on_commit=True'), kv=KV([['True', f"n.ver = {st['True'][2]}(新)"], ['False', f"n.ver = {st['False'][2]}(旧)"]], ['False'])),
    step(f"数据库侧改的列(触发器、默认值、onupdate)同理:更新并 commit 后,expire_on_commit=True 的对象 n.ver 是 {tg['True'][1]}(和库里实际的 {tg['True'][2]} 一致);False 的对象 n.ver 还是 {tg['False'][1]},库里实际是 {tg['False'][2]}。关掉过期后,凡是数据库自己会改的列,要么用 RETURNING 取回,要么手动 refresh。", t=tl(S(4)), mark=lidx(S(4), 'expire_on_commit=False'), done=lidx(S(4), 'expire_on_commit=True'), kv=KV([['触发器改的列', 'False 时对象里是旧值'], ['补救', 'refresh 或 RETURNING']], ['触发器改的列'])),
    step(f"代价:commit 1000 个对象之后逐个读 title,expire_on_commit=True {cs['True'][0]:.1f} ms、{cs['True'][1]} 条 SQL(每个对象各一条 SELECT);False {cs['False'][0]:.1f} ms、{cs['False'][1]} 条。这是 N+1 的另一个来源。", b=bars([['True', cs['True'][0], f"{cs['True'][0]:.0f} ms"], ['False', max(cs['False'][0], 0.05), f"{cs['False'][0]:.1f} ms"]], cs['True'][0], mark=[0], done=[1]), t=tl(S(5)), mark=lidx(S(5), 'expire_on_commit=True'), done=lidx(S(5), 'expire_on_commit=False'), kv=KV([['True', f"{cs['True'][1]} 条 SQL"], ['False', f"{cs['False'][1]} 条 SQL"]], ['True'])),
]
A = mkartf('f93', 93, 'Flask,SQLAlchemy,expire_on_commit,Session,真实验证,动画演示',
    f'在真实的 PostgreSQL 上实测 expire_on_commit:默认 commit 之后读属性多发 1 条 SELECT、请求结束后读属性抛 DetachedInstanceError、关掉后读到旧值(触发器改的 ver 对象里是 {tg["False"][1]} 而库里是 {tg["False"][2]})、commit 1000 个对象后逐个读属性 {cs["True"][1]} 条 SQL 对 0 条。',
    'expire_on_commit 默认是 True,它到底在做什么?关掉它能省多少、会丢什么?这篇用真实的 PostgreSQL 和一个会改列的触发器,把两种设置下 commit 之后的对象逐项对照。',
    [(f'{cs["True"][1]} → 0', 'commit 1000 个对象后逐个读属性的 SQL 条数(True 与 False)'), ('DetachedInstanceError', '默认设置下请求结束后读 commit 过的对象的属性'), (f'{tg["False"][1]} vs {tg["False"][2]}', '关掉过期后,触发器改过的 ver:对象里的值与库里的值')],
    [('commit 之后读属性', '<p>上一篇:<a href="flask-pool-checkout-release.html">Pool Checkout 与连接释放</a>;下一篇:<a href="flask-optimistic-lock.html">乐观锁</a>。</p>'), ('请求之外读属性', None), ('陈旧数据', None), ('数据库侧改的列', None), ('代价', None)],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1(session_options={"expire_on_commit": False})、psycopg 3.3.6、自己起的 PostgreSQL(非默认端口,表上有一个 BEFORE UPDATE 触发器)', '没有验证:只对部分对象关闭过期(session.expire_on_commit 的局部修改)、eager_defaults 选项、异步 Session 下为什么强烈建议关闭、关闭后配合 refresh 的最佳实践'], 'expire_on_commit', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时'), ('kv', 'kv', '要点')])
